// Config + request check. Fails loudly when the Firebase project id is not configured.
const proj = String($env.FIREBASE_PROJECT_ID || '').trim();
if (!proj) throw new Error('FIREBASE_PROJECT_ID env var is not set (set it on the n8n container)');
const body = $('Dispatch maango (webhook)').first().json.body || {};
const docId = typeof body.doc_id === 'string' ? body.doc_id : '';
// Firestore auto-ids are 20 characters of [A-Za-z0-9]; anything else (slashes, paths, odd ids) is refused
if (!/^[A-Za-z0-9]{20}$/.test(docId)) return [{ json: { ok: false, error: 'bad request' } }];
return [{ json: { ok: true, doc_id: docId } }];

// F2: only a real, brand-new, unassigned, recent job can be dispatched. The stored job is the
// source of truth: the request's area (or anything else it sends) is ignored.
const j = $input.first().json || {};
const docId = $('Request check').first().json.doc_id;
const no = why => [{ json: { ok: false, error: 'not assignable', why, doc_id: docId } }];
if (j.error || !j.service) return no('no such job');
if (j.status !== 'new') return no('status is not new');
if (j.washer_id) return no('already assigned');
const tms = v => {
  if (!v) return NaN;
  if (typeof v === 'string') return new Date(v).getTime();
  if (v instanceof Date) return v.getTime();
  if (typeof v === 'object') {
    const s = v._seconds != null ? v._seconds : v.seconds;
    return s != null ? Number(s) * 1000 : NaN;
  }
  return NaN;
};
const created = tms(j.created_at), now = Date.now();
if (!Number.isFinite(created) || now - created > 15 * 60 * 1000 || created - now > 5 * 60 * 1000) return no('not fresh');
const price = Number(j.price);
const area = String(j.area || '');                        // the stored area, not the request's
const orderId = String(j.pay_ref || '');
const base = { ok: true, doc_id: docId, area, price, reg: String(j.reg || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase() };
// Pay on arrival: paid is not true and there is no pay_ref. Dispatched as before, no Cashfree call;
// the washer collects the cash.
if (j.paid !== true && !orderId && Number.isFinite(price) && price > 0) {
  return [{ json: { ...base, orderId: '', cash: true } }];
}
// paid=true must carry a Cashfree order id that we can check
if (j.paid !== true || !Number.isFinite(price) || price <= 0 || !/^[A-Za-z0-9_-]{1,50}$/.test(orderId)) {
  return [{ json: { ...base, orderId: '', why: 'job is not marked as paid' } }];
}
return [{ json: { ...base, orderId } }];

// GPS auto-dispatch: pick the nearest active washer to the customer's area.
// 'Active' means their location doc was updated within the last 30 minutes.

// Approximate centre-point coordinates for each service area (Paschim Vihar, Delhi).
const AREA_COORDS = {
  'GH-9 Paschim Vihar':    {lat: 28.6680, lng: 77.0989},
  'GH-6 Paschim Vihar':    {lat: 28.6695, lng: 77.0970},
  'GH-14 Paschim Vihar':   {lat: 28.6705, lng: 77.0982},
  'Meera Bagh':             {lat: 28.6720, lng: 77.1065},
  'Sundar Vihar':           {lat: 28.6710, lng: 77.1110},
  'Guru Hari Apartments':   {lat: 28.6650, lng: 77.0960},
};

function haversine(lat1, lng1, lat2, lng2) {
  const R = 6371000; // metres
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 +
    Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLng/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

// Job validated and payment verified upstream. doc id and area come from the STORED job
// ('Job check'), never from the request.
const job = $('Job check').first().json;
const docId = job.doc_id;
const area  = job.area;

// All location docs read by the Firestore node.
const now = Date.now();
const STALE_MS = 30 * 60 * 1000; // 30 min

const active = $input.all()
  .map(i => i.json)
  .filter(loc => {
    if (!loc.washer_id || !loc.lat || !loc.lng) return false;
    // updated_at is an IST ISO string like "2026-10-18T06:42:00+05:30"
    const age = now - new Date(loc.updated_at).getTime();
    return age <= STALE_MS;
  });

if (!active.length) {
  // No washer is broadcasting GPS — leave washer_id blank so both get the job alert.
  return [{json: {ok: true, assigned: false, reason: 'no_active_washers', doc_id: docId}}];
}

const target = AREA_COORDS[area];
if (!target) {
  // Unknown area — pick the washer with the most recent location update.
  active.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at));
  return [{json: {ok: true, assigned: true, washer_id: active[0].washer_id, doc_id: docId, method: 'newest'}}];
}

// Nearest active washer by Haversine distance.
let best = null, bestDist = Infinity;
for (const loc of active) {
  const d = haversine(loc.lat, loc.lng, target.lat, target.lng);
  if (d < bestDist) { bestDist = d; best = loc; }
}

return [{json: {ok: true, assigned: !!best, washer_id: best ? best.washer_id : null, doc_id: docId, dist_m: Math.round(bestDist), method: 'nearest'}}];

// F3: the browser saying "paid" proves nothing. Cashfree's own record of the order must say PAID,
// in rupees, for exactly the price stored on the job, and the order can pay for one job only.
const job = $('Job check').first().json;
const cf = $input.first().json || {};
const bad = why => [{ json: { ok: false, paid: false, why } }];
if (cf.error || cf.code || cf.type === 'invalid_request_error' || !cf.order_id) return bad('Cashfree has no such order');
if (String(cf.order_id) !== job.orderId) return bad('order id mismatch');
if (String(cf.order_status || '').toUpperCase() !== 'PAID') return bad('order status is ' + String(cf.order_status || '?').slice(0, 20));
if (String(cf.order_currency || '').toUpperCase() !== 'INR') return bad('order currency is not INR');
if (Number(cf.order_amount) !== Number(job.price)) return bad('paid ' + Number(cf.order_amount) + ' but the job price is ' + job.price);
const tags = cf.order_tags || {};
if (tags.reg && job.reg && String(tags.reg).replace(/[^A-Za-z0-9]/g, '').toUpperCase() !== job.reg) return bad('order is for another car');
// one paid order = one job: remember order -> job (bounded to the last 500)
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.usedOrders)) sd.usedOrders = [];
const prev = sd.usedOrders.find(u => u.o === job.orderId);
if (prev && prev.d !== job.doc_id) return bad('order already used for another job');
if (!prev) { sd.usedOrders.push({ o: job.orderId, d: job.doc_id }); if (sd.usedOrders.length > 500) sd.usedOrders = sd.usedOrders.slice(-500); }
return [{ json: { ok: true, paid: true } }];

// Unpaid or unverifiable job: Ravi hears about it, once per job (bounded list), no loops.
const job = $('Job check').first().json;
const why = String(($input.first().json || {}).why || job.why || 'unknown').slice(0, 120);
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.unpaidAlerted)) sd.unpaidAlerted = [];
if (sd.unpaidAlerted.includes(job.doc_id)) return [];
sd.unpaidAlerted.push(job.doc_id);
if (sd.unpaidAlerted.length > 200) sd.unpaidAlerted = sd.unpaidAlerted.slice(-200);
return [{ json: { text: '⚠ On-demand job NOT dispatched (payment not confirmed): ' + why +
  '\nJob ' + job.doc_id + ' - ₹' + (job.price || '?') + (job.reg ? ' - ' + job.reg : '') +
  '\nCheck Cashfree, then assign a washer by hand if it was really paid.' } }];
